-- Local replay required before any staging promotion.
-- OTOTR EXPENSE APPROVE RPC CANDIDATE
create or replace function finance_api.authorize_expense_approve(p_expense_id uuid,p_permission text) returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and p_permission='finance.expenses.approve' and finance_private.resolve_expense_approval_scope(auth.uid(),p_expense_id,p_permission)$$;
create or replace function finance_api.commit_expense_approve(p_actor_id uuid,p_expense_id uuid,p_expected_version bigint,p_reason_code text,p_note_hash text,p_idempotency_key text,p_intent_hash text,p_correlation_id uuid) returns jsonb language plpgsql security definer set search_path=pg_catalog,finance,finance_private as $$declare e finance.pass_through_expenses%rowtype;ar finance.approval_requests%rowtype;step finance.approval_steps%rowtype;existing jsonb;current_snapshot jsonb;current_hash text;new_version bigint;payload jsonb;previous text;audit_hash text;begin if not finance_private.current_expense_approval_committer_is_trusted() then raise exception using errcode='42501',message='trusted expense approval committer required';end if;if p_expected_version<1 or length(btrim(coalesce(p_idempotency_key,''))) not between 8 and 200 or p_intent_hash!~'^[a-fA-F0-9]{64}$' or (p_note_hash is not null and p_note_hash!~'^[a-fA-F0-9]{64}$') then raise exception using errcode='22023',message='invalid expense approve command';end if;select * into e from finance.pass_through_expenses where id=p_expense_id for update;if not found then raise exception using errcode='P0002',message='expense not found';end if;select om.payload into existing from finance.outbox_messages om where om.legal_entity_id=e.legal_entity_id and om.event_type='PASS_THROUGH_EXPENSE_APPROVED' and om.aggregate_id=e.id and om.payload->>'idempotencyKey'=p_idempotency_key order by om.created_at_utc desc,om.id desc limit 1;if found then if existing->>'intentHash'=p_intent_hash then return pg_catalog.jsonb_build_object('outcome','REPLAY','expenseId',e.id,'status','APPROVED','version',(existing->>'version')::bigint,'approvalRequestId',existing->>'approvalRequestId','snapshotHash',existing->>'snapshotHash');end if;return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;if e.status<>'PENDING_APPROVAL' or e.version<>p_expected_version then return pg_catalog.jsonb_build_object('outcome','CONFLICT');end if;if e.prepared_by=p_actor_id then raise exception using errcode='42501',message='maker checker violation';end if;select * into ar from finance.approval_requests x where x.legal_entity_id=e.legal_entity_id and x.subject_type='PASS_THROUGH_EXPENSE' and x.subject_id=e.id and x.status='PENDING' for update;if not found or ar.prepared_by<>e.prepared_by or ar.subject_snapshot is null or ar.subject_snapshot_hash is null then raise exception using errcode='23514',message='pending immutable expense approval snapshot required';end if;select * into step from finance.approval_steps s where s.approval_request_id=ar.id and s.step_no=1 and s.required_role='finance-expense-approver' for update;if not found or step.decision is not null then raise exception using errcode='23514',message='pending expense approver step required';end if;current_snapshot:=finance_private.build_expense_approval_snapshot(e.id);current_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(current_snapshot::text,'UTF8'),'sha256'),'hex');if current_hash<>ar.subject_snapshot_hash or current_snapshot<>ar.subject_snapshot then raise exception using errcode='40001',message='expense approval snapshot changed';end if;update finance.approval_steps set decision='APPROVE',decided_by=p_actor_id,decided_at_utc=pg_catalog.statement_timestamp(),evidence_ref='EXPENSE_APPROVAL:'||p_correlation_id::text where id=step.id;update finance.approval_requests set status='APPROVED',version=version+1,correlation_id=p_correlation_id where id=ar.id;new_version:=e.version+1;update finance.pass_through_expenses set status='APPROVED',approved_by=p_actor_id,version=new_version,correlation_id=p_correlation_id where id=e.id;payload:=pg_catalog.jsonb_build_object('expenseId',e.id,'approvalRequestId',ar.id,'snapshotHash',current_hash,'version',new_version,'idempotencyKey',p_idempotency_key,'intentHash',p_intent_hash,'reasonCode',p_reason_code,'noteHash',p_note_hash);insert into finance.outbox_messages(legal_entity_id,topic,event_type,aggregate_type,aggregate_id,aggregate_version,payload,payload_hash,status,correlation_id) values(e.legal_entity_id,'finance.expense','PASS_THROUGH_EXPENSE_APPROVED','PASS_THROUGH_EXPENSE',e.id,new_version,payload,current_hash,'PENDING',p_correlation_id);perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('audit:'||e.legal_entity_id::text,0));select integrity_hash into previous from finance.audit_events where legal_entity_id=e.legal_entity_id order by created_at_utc desc,id desc limit 1;audit_hash:=pg_catalog.encode(extensions.digest(pg_catalog.convert_to(coalesce(previous,'GENESIS')||':'||e.id::text||':PASS_THROUGH_EXPENSE_APPROVED:'||current_hash||':'||p_correlation_id::text,'UTF8'),'sha256'),'hex');insert into finance.audit_events(legal_entity_id,actor_id,actor_type,action_code,subject_type,subject_id,decision,reason_code,before_hash,after_hash,previous_integrity_hash,integrity_hash,safe_context,correlation_id) values(e.legal_entity_id,p_actor_id,'USER','PASS_THROUGH_EXPENSE_APPROVED','PASS_THROUGH_EXPENSE',e.id,'ALLOW',p_reason_code,current_hash,current_hash,previous,audit_hash,pg_catalog.jsonb_build_object('approvalRequestId',ar.id,'approvalStepId',step.id,'preparedBy',e.prepared_by,'approvedBy',p_actor_id,'noteHash',p_note_hash,'previousVersion',e.version),p_correlation_id);return pg_catalog.jsonb_build_object('outcome','APPROVED','expenseId',e.id,'status','APPROVED','version',new_version,'approvalRequestId',ar.id,'snapshotHash',current_hash);end$$;
revoke all on function finance_api.authorize_expense_approve(uuid,text) from public,anon;grant execute on function finance_api.authorize_expense_approve(uuid,text) to authenticated;revoke all on function finance_api.commit_expense_approve(uuid,uuid,bigint,text,text,text,text,uuid) from public,anon,authenticated;
